/*Step 1.1. Specifying Options */
%let begdate = mdy(1,1,1998);
%let enddate = mdy(12,31,2012);

/*Step 1.2. Get CRSP Prices, Returns, and Adjustment Factors from CRSP.msf Dataset */
data Price; set CRSP.msf;
if &begdate<=date<=&enddate;
tso=shrout*cfacshr*1000;
vol_adj=vol*cfacshr*100;
if cfacpr ne 0 then prc_adj = abs(prc)/cfacpr; else prc_adj=.;
absprc=abs(prc);
mnindex=(year(date)-1990)*12+month(date);
if tso>0; if prc_adj ne .; if ret>-1;
label tso = "Total Shares Outstanding, Adjusted";
label prc_adj = "Price at Period t End, Adjusted";
keep permno date mnindex tso prc_adj absprc cfacshr ret HEXCD;

/*Step 1.3. Get report and vintage dates (Fdate) from Thomson Mutual Fund Holdings */
/*Exclude Non-Equity Funds */
proc sql;
create table First_Vint
as select distinct intnx("month",rdate,0,"E") as rdate, fdate, fundno,fundname,ioc, mgrcoab 
from TR.S12type1
where (&begdate<= rdate <=&enddate and ioc not in (1,5,6,7))
group by fundno, intnx("month",rdate,0,"E")
having fdate=min(fdate) and max(rdate)=rdate
order by fundno, rdate desc;
quit;

/*Step 1.4. Add WFICN portfolio identifiers from MFLINKS */
proc sql; create table Hret1 as select a.*, b.wficn from Hret0 as a, MFL.Mflink2_beg_end as b where a.fundno=b.fundno and b.linkdate1<=a.fdate<=b.linkdate2; quit;
proc sort data=Hret1 nodupkey; by wficn mnindex; run;

/*Step 1.5. Extract Holdings by Merging Thomson S12type1 and S12type3 datasets */
/*Add Holdings Data */
proc sql;
create table temp1
as select a.wficn, a.fundno, a.fundname, a.mnindex, a.rdate, a.fdate, a.ioc, a.mgrcoab, b.cusip, b.shares
from Hret1 as a, TR.s12type3 as b
where a.fundno=b.fundno and a.fdate=b.fdate;
quit;

/*Map Holdings CUSIP to CRSP Unique Identifier PERMNO */
proc sql; create table temp2 as select a.*, b.permno from temp1 as a, msenames as b where a.cusip=b.ncusip; quit;
proc sort nodupkey data=temp2; by wficn mnindex permno; run;

/*Step 1.6. Add CRSP Market Data to Holdings: Prc_adj and ret */
/*Use holding dollar value at month(t-3) as weights for buy & hold portfolio 3-month returns */
/*Use holding dollar value at month(t-6) as weights for buy & hold portfolio 6-month returns */

*3-month buy-and-hold return;
proc sql; create table temp01 as select distinct permno,mnindex,(exp(sum(log(1+mret)))-1) as cret from temp00 group by permno,mnindex having count(mret)=3; quit;

proc sql;
Create table temp00
as select a.*, b.date as pdate, b.ret as mret
from temp0 as a, Price as b
where a.permno=b.permno and a.mnindex-5<=b.mnindex<=a.mnindex;
*6-month buy-and-hold return;
proc sql; create table temp02 as select distinct permno,mnindex,(exp(sum(log(1+mret)))-1) as cret from temp00 group by permno,mnindex having count(mret)=6; quit;

/* Check for Duplicates */
data Hret4; set Hret3; proc sort nodupkey; by wficn mnindex permno; run;

*save the data;
data WD.holdings_wficn; set Hert4; Hvalue_0=shares_adj*prc_adj; run;

/*Step 2.3. Get CRSP Mutual Fund, Monthly Net Returns */
/*Net Returns include distributions (dividends and capital gains) but net of total expenses (CRSP MFDB manual, page 6) */
data Monthly_Returns; set CRSPF.Monthly_Returns;
if mret ne .;
mnindex=(year(caldt)-1990)*12+month(caldt);
keep crsp_fundno caldt mnindex mret;
proc sort nodupkey; by crsp_fundno mnindex;
run;

data Monthly_Tna; set CRSPF.Monthly_Tna;
if mtna ne .;
mnindex=(year(caldt)-1990)*12+month(caldt);
keep crsp_fundno caldt mnindex mtna;
proc sort nodupkey; by crsp_fundno mnindex;
run;

proc sql;
create table temp1
as select a.crsp_fundno,a.caldt,a.mret,a.mnindex, b.mtna
from Monthly_Returns as a, Monthly_Tna as b
where a.crsp_fundno=b.crsp_fundno and a.mnindex=b.mnindex;
quit;

*require crsp_fundno in Equity_Funds;
proc sql; create table temp2 as select a.* from temp1 as a, Equity_Funds as b where a.crsp_fundno=b.crsp_fundno; quit;

/*Extracting and linking expense ratio data to get Raw Return */
data Fund_Fees; set CRSPF.Fund_Fees;
if exp_ratio ne .;
proc sort nodupkey; by crsp_fundno begdt enddt;
run;

proc sql;
create table temp3
as select a.*, b.exp_ratio
from temp2 as a left join Fund_Fees as b
on a.crsp_fundno=b.crsp_fundno and b.begdt<=a.caldt<=b.enddt;

/*Step 2.5. Merge with Fund Identifier from MFLINKS */
proc sql;
create table temp5
as select a.*, b.wficn
from temp4 as a, MFL.Mflink1 as b
where a.crsp_fundno=b.crsp_fundno and not missing(b.wficn);
quit;

*Rret1 is wficn-mnindex-fundno level, Rret1_wficn is wficn-mnindex level;
data Rret1_wficn; set Rret1; drop crsp_fundno; proc sort nodupkey; by wficn mnindex; run;

*save the data;
data WD.mret_wficn; set Rret1_wficn; run;

***Rret3, calculate 3-month and 6-month portfolio returns; *using rret1(raw returns);
data temp0; set Rret1_wficn; keep wficn mnindex; proc sort nodupkey; by wficn mnindex;
proc sql; create table temp01 as select a.*, b.rret1 from temp0 as a, Rret1_wficn as b where a.wficn=b.wficn and a.mnindex-2<=b.mnindex<=a.mnindex;
*3-month buy-and-hold return;
proc sql; create table temp11 as select wficn,mnindex,(exp(sum(log(1+rret1)))-1) as cret from temp01 group by wficn,mnindex having count(rret1)=3; quit;

proc sql; create table temp02 as select a.*, b.rret1 from temp0 as a, Rret1_wficn as b where a.wficn=b.wficn and a.mnindex-5<=b.mnindex<=a.mnindex;
*6-month buy-and-hold return;
proc sql; create table temp12 as select wficn,mnindex,(exp(sum(log(1+rret1)))-1) as cret from temp02 group by wficn,mnindex having count(rret1)=6; quit;

data WD.WD_measure; set temp1;
WD3 = HRET3 - RRET3;
WD6 = HRET6 - RRET6;
label WD3="WD 3-month";
label WD6="WD 6-month";
year=year(rdate); qtr=qtr(rdate); yrqtr=year*100+qtr; yrqtrc=cats(year,'Q',qtr); format yrqtrc $6.;
if assets>0; if tna>0; if tna_3>0; 
size=log(Assets); 
if WD3 ne .; if size ne .; if sizetna ne .;
keep wficn mnindex rdate year qtr yrqtr yrqtrc fundname ioc mgrcoab WD3 WD6 Hret3 Hret6 Rret3 Rret6 Assets tna size;

/*Step 1.1. Specifying Options */
%let begdate = mdy(1,1,1998); *CRSPF.Daily_Returns Begins from September 2,1998;
%let enddate = mdy(12,31,2012);

/*Step 1.2. Get CRSP Prices, Returns, and Adjustment Factors from CRSP.dsf Dataset */
data Price0; set CRSP2017.dsf; 
if &begdate<=date<=&enddate;
tso=shrout*cfacshr*1000;
if vol=-99 then vol=.;
vol_adj = abs(vol)*cfacshr; 
if cfacpr ne 0 then prc_adj = abs(prc)/cfacpr; else prc_adj=.;
value=tso*prc_adj;
if tso>0; if prc_adj ne .; if ret>-1;
mnindex=(year(date)-1990)*12+month(date);
keep permno date mnindex ret prc_adj vol_adj cfacshr tso value;

/*Step 1.3. Get report and vintage dates (Fdate) from Thomson-Reuters Mutual Fund Holdings */
/*Exclude Non-Equity Funds */
proc sql;
create table First_Vint
as select distinct intnx("month",rdate,0,"E") as rdate, fdate, fundno, ioc, mgrcoab
from TR.S12type1
where (&begdate<= rdate <=&enddate and ioc not in (1,5,6,7))
group by fundno, intnx("month",rdate,0,"E")
having fdate=min(fdate) and max(rdate)=rdate
order by fundno, rdate desc;

/*Step 1.4. Add WFICN portfolio identifiers from MFLINKS */
proc sql; create table Hret1 as select a.*, b.wficn from Hret0 as a, MFL.Mflink2_beg_end as b where a.fundno=b.fundno and b.linkdate1<=a.fdate<=b.linkdate2; quit;
proc sort data=Hret1 nodupkey; by wficn mnindex; run;

/*Step 1.5. Extract Holdings by Merging TR S12type1 and S12type3 datasets */
/*Add Holdings Data */
proc sql;
create table temp1
as select a.wficn, a.fundno, a.mnindex, a.rdate, a.fdate, a.ioc, a.mgrcoab, b.cusip, b.shares
from Hret1 as a, TR.s12type3 as b
where a.fundno=b.fundno and a.fdate=b.fdate;
quit;

/*Map Holdings CUSIP to CRSP Unique Identifier PERMNO */
data msenames; set crsp.msenames; if ncusip ne ''; if permno ne .; proc sort nodupkey; by permno ncusip;

proc sql; create table temp2 as select a.*, b.permno from temp1 as a, msenames as b where a.cusip=b.ncusip; quit;

/*Step 2.3. Get CRSP Mutual Fund, Daily Net Returns */
/*Net Returns include distributions (dividends and capital gains) but net of total expenses (CRSP MFDB manual, page 6) */
data Daily_Returns; set CRSPF.Daily_Returns;
if &begdate<=caldt<=&enddate;
if dret ne .;
mnindex=(year(caldt)-1990)*12+month(caldt);
keep crsp_fundno caldt mnindex dret;
proc sort nodupkey; by crsp_fundno mnindex caldt;
run;

*use Monthly_Tna, Monthly_Nav, Daily_Nav to calculate Daily_Tna;
data Monthly_Tna; set CRSPF.Monthly_Tna;
if mtna ne .;
mnindex=(year(caldt)-1990)*12+month(caldt);
keep crsp_fundno caldt mnindex mtna;
proc sort nodupkey; by crsp_fundno mnindex;
run;

data Monthly_Nav; set CRSPF.Monthly_Nav;
if mnav ne .;
mnindex=(year(caldt)-1990)*12+month(caldt);
keep crsp_fundno caldt mnindex mnav;
proc sort nodupkey; by crsp_fundno mnindex;
run;

proc sql; create table temp1 as select a.*, b.mnav from Monthly_Tna as a, Monthly_Nav as b where a.crsp_fundno=b.crsp_fundno and a.mnindex=b.mnindex; quit;
data temp2; set temp1; shares=mtna/mnav; run;

data Daily_Nav; set CRSPF.Daily_Nav;
if dnav ne .;
mnindex=(year(caldt)-1990)*12+month(caldt);
keep crsp_fundno caldt mnindex dnav;
proc sort nodupkey; by crsp_fundno mnindex caldt;
run;

proc sql; create table temp3 as select a.*, b.shares from Daily_Nav as a left join temp2 as b on a.crsp_fundno=b.crsp_fundno and a.mnindex=b.mnindex; quit;
data Daily_tna; set temp3; dtna=dnav*shares; run;

/* Step 2.5. Merge with Fund Identifier from MFLINKS */
proc sql;
create table Rret5
as select a.*, b.wficn
from Rret4 as a, MFL.Mflink1 as b
where a.crsp_fundno=b.crsp_fundno and not missing(b.wficn);

/* Step 2.6. Aggregate multiple share classes, use lagged TNA as weights */
/* Compute monthly net and raw returns, TNA and expense ratio at the fund level */
proc sql;
create table Rret6
as select wficn, mnindex, caldt, crsp_fundno, sum(tna) as tna, /*******************************TNA is summarized to Fund level*/
    count(crsp_fundno) as nclass label='# of Share Classes',
    sum(dret*portw)/sum(portw) as dret1,          /***********************dret(net) is value weighted summarized to Fund level*/
    sum(rret*portw)/sum(portw) as rret1,          /***********************rret(raw) is value weighted summarized to Fund level*/
	mean(rret) as rret2                           /***********************rret(raw) is equal weighted summarized to Fund level*/
from Rret5
group by wficn, mnindex, caldt;
quit;

*Rret6 is wficn-date-fundno level, Rret6_wficn is wficn-date level;
data Rret6_wficn; set Rret6; drop crsp_fundno; proc sort nodupkey; by wficn mnindex caldt; run;

*save the data;
data WD.Dret_wficn; set Rret6_wficn; run;

/* Step 3. Combining Hypothetical Holdings Returns with CRSP Total Returns */
proc sort data=Hret6_wficn nodupkey; by wficn mnindex date;          *wficn-qtr-date(90) level;
proc sort data=Rret6_wficn nodupkey; by wficn mnindex caldt; run;    *wficn-date level;
proc sql;
create table temp1
as select a.*, b.Rret1, b.Rret2
from Hret6_wficn as a, Rret6_wficn as b
where a.wficn=b.wficn and a.date=b.caldt;
quit;

data WD.wd_daily; set temp1;
WD1 = HRET1 - RRET1; 
WD2 = HRET2 - RRET2; 
keep wficn mnindex rdate date HRET1 RRET1 HRET2 RRET2 WD1 WD2 ;
proc sort nodupkey; by wficn mnindex date;
run;

*FF.factors_daily dataset contains daily four factors (from Frechn's website) and adjusted daily momentum factor;
*For adjusted momentum factors, following Agarwal et al. (2014), we use different evaluation periods, 
(e.g., 3 months for 'mom_1' or 6 months for 'mom_3'), instead of French's 11 months.;
*In addition, we define winner (loser) stocks as the top (bottom) 20% performers during the evaluation period.;

*choose 3-month period;
data wd_daily_3m; set WD.wd_daily; if 0<=rdate-date<=90;run;

proc sql;
create table regdata 
as select a.date,mom_1,mom_3, b.*
from FF.factors_daily as a, wd_daily_3m as b where a.date=b.date;

*choose 3-month period;
data wd_daily_3m; set WD.wd_daily; if 0<=rdate-date<=90;run;

proc sql;
create table regdata 
as select a.date,mom_1,mom_3, b.*
from FF.factors_daily as a, wd_daily_3m as b where a.date=b.date;

*choose 6-month period;
data wd_daily_6m; set WD.wd_daily; if 0<=rdate-date<=180;run;

proc sql;
create table regdata 
as select a.date,mom_3, b.*
from FF.factors_daily as a, wd_daily_6m as b where a.date=b.date;

data temp2; set temp1; proc sort; by wficn mnindex dif; where n>=40; run;

*60-day WD residual;
proc means data=temp2 noprint; where dif>=30;
by wficn mnindex; 
var alpha_v3;
output out=alpha60 mean=wd60_v3;
run;

*80-day WD residual;
proc means data=temp2 noprint; where dif>=10;
by wficn mnindex; 
var alpha_v1 alpha_v3 ;
output out=alpha80 mean=wd80_v1 wd80_v3 ;
run;

*Merge 60-day and 80-day;
proc sql;
create table WD3 
as select a.*,a._freq_ as n60, c.*,c._freq_ as n80
from alpha60 as a, alpha80 as c where a.wficn=c.wficn and a.mnindex=c.mnindex;
quit;

data WD3MomAdj; set WD3; wd80_v1=wd80_v1*90; wd60_v3=wd60_v3*90; wd80_v3=wd80_v3*90; drop _freq_ _n_; run;

data WD6MomAdi; set alpha170; wd170_v3=wd170_v3*180; drop _freq_ _n_;
run;


*Merge 3-month WD_MomAdj and 6-month WD_MomAdj;
proc sql;
create table WD.WD_MomAdj_measure 
as select a.*, b.*
from WD3MomAdj as a left join WD6MomAdj as b on a.wficn=b.wficn and a.mnindex=b.mnindex;

%macro sepyr;
%do i = 1 %to 15;
data temp1; set Hret2; 
if year(rdate)=1997+&i;

proc sql;
Create table temp2
as select distinct a.*, b.date,b.prc_lag, b.ret
from temp1 as a left join Price1 as b
on a.permno=b.permno and a.mnindex-5<=b.mnindex<=a.mnindex; *daily returns in prior 6 months;
quit;

/*Step 1.7. Calculate Hypothetical Holdings Returns*/
data temp3; set temp2;
if prc_lag ne .; if ret ne .; 
value_lag=shares_adj*prc_lag;
proc sort; by wficn mnindex date;
run;

proc means data=temp3 noprint;
by wficn mnindex date;
var ret;
weight VALUE_lag;
output out=temp41 (drop=_TYPE_ _FREQ_) N=NSTOCKS MEAN=HRET1 SUMWGT=Assets;
run;

proc means data=temp3 noprint;
by wficn mnindex date;
var ret;
output out=temp42 (drop=_TYPE_ _FREQ_) MEAN=HRET2;
run;

data temp5&i; merge temp41 temp42; by wficn mnindex date; run;

%macro comb;
data Hret3;
  set
   %do i = 1 %to 15;
     temp5&i
   %end; 
   ;
run;
%mend;
%comb;
